second-largest.javascript:
const fs = require('fs');
const tokens = fs.readFileSync(0, 'utf-8').trim().split(/\s+/).filter(Boolean);
if (tokens.length >= 2) {
  const n = parseInt(tokens[0], 10);
  const nums = Array.from(new Set(tokens.slice(1, n + 1).map(Number))).sort((a, b) => a - b);
  console.log(nums.length < 2 ? -1 : nums[nums.length - 2]);
} else {
  console.log(-1);
}

move-zeroes.javascript:
const fs = require('fs');
const tokens = fs.readFileSync(0, 'utf-8').trim().split(/\s+/).filter(Boolean);
if (tokens.length >= 1) {
  const n = parseInt(tokens[0], 10);
  const nums = tokens.slice(1, n + 1).map(Number);
  const nonZero = nums.filter(x => x !== 0);
  const zeros = new Array(nums.length - nonZero.length).fill(0);
  console.log([...nonZero, ...zeros].join(' '));
}

contains-duplicate.javascript:
const fs = require('fs');
const tokens = fs.readFileSync(0, 'utf-8').trim().split(/\s+/).filter(Boolean);
if (tokens.length >= 1) {
  const n = parseInt(tokens[0], 10);
  const nums = tokens.slice(1, n + 1);
  const unique = new Set(nums);
  console.log(unique.size !== nums.length ? 'true' : 'false');
}

