is-palindrome.javascript:
const fs = require('fs');
const text = fs.readFileSync(0, 'utf-8').replace(/[\r\n]+$/, '');
const filtered = text.toLowerCase().replace(/[^a-z0-9]/g, '');
const reversed = filtered.split('').reverse().join('');
console.log(filtered === reversed ? 'true' : 'false');

count-vowels.javascript:
const fs = require('fs');
const text = fs.readFileSync(0, 'utf-8').replace(/[\r\n]+$/, '');
let v = 0, c = 0;
for (const ch of text) {
  if (/[a-zA-Z]/.test(ch)) {
    if (/[aeiouAEIOU]/.test(ch)) v++;
    else c++;
  }
}
console.log(`Vowels: ${v}, Consonants: ${c}`);

check-anagram.javascript:
const fs = require('fs');
const lines = fs.readFileSync(0, 'utf-8').split(/\r?\n/);
const s1 = (lines[0] || '').replace(/\s+/g, '').split('').sort().join('');
const s2 = (lines[1] || '').replace(/\s+/g, '').split('').sort().join('');
console.log(s1 === s2 ? 'true' : 'false');

first-non-repeating.javascript:
const fs = require('fs');
const text = fs.readFileSync(0, 'utf-8').trim();
const counts = {};
for (const ch of text) counts[ch] = (counts[ch] || 0) + 1;
let found = '-1';
for (const ch of text) {
  if (counts[ch] === 1) {
    found = ch;
    break;
  }
}
console.log(found);
